contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool allCallsSucceeded = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool _s,) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v));
            if (!_s) {
                allCallsSucceeded = false;
                break;
            }
        }

        uint before = address(c).balance;
        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBal = address(c).balance;

        assert(allCallsSucceeded ? (reverted || afterBal == before) : reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        uint before = address(c).balance;
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool _ret) {
            reverted = false;
            ret = _ret;
        } catch {
            reverted = true;
        }
        uint afterBal = address(c).balance;
        assert(reverted || (ret == true && afterBal == before));
    }

    receive() external payable {}
}

